import json
import xml.etree.ElementTree as ET

from pathlib import Path


def apply_translation_corrections(directory, project_id):

    directory = Path(directory)

    applied = []
    skipped = []

    prepared = {}

    for rule in RULES:

        filename = (
            project_id + "_" +
            rule["language"] + ".ts"
        )

        path = directory / filename

        if not path.is_file():

            skipped.append({
                "language": rule["language"],
                "source": rule["source"],
                "reason": "catalogue_not_present",
            })

            continue

        if path not in prepared:
            prepared[path] = ET.parse(path)

        tree = prepared[path]

        matches = []

        for context in tree.getroot().findall("context"):

            if context.findtext("name") != rule["context"]:
                continue

            for message in context.findall("message"):

                if (
                    message.findtext("source", "") ==
                    rule["source"]
                    and message.findtext("comment", "") ==
                    rule["comment"]
                    and message.get("numerus", "no") ==
                    rule["numerus"]
                ):

                    matches.append(message)

        if not matches:

            skipped.append({
                "language": rule["language"],
                "source": rule["source"],
                "reason": "source_key_not_present",
            })

            continue

        if len(matches) != 1:

            raise ValueError(
                f"Ambiguous correction: {filename}"
            )

        translation = matches[0].find("translation")

        if translation is None:
            raise ValueError("Missing translation")

        forms = translation.findall("numerusform")

        if not forms:
            forms = [translation]

        if any(len(form) for form in forms):

            raise ValueError(
                "Complex translation requires review"
            )

        actual = [
            "".join(form.itertext())
            for form in forms
        ]

        if (
            actual != rule["original_forms"]
            or translation.attrib !=
                rule["original_attributes"]
        ):

            raise ValueError(
                "Correction requires renewed review: "
                f"{filename}: {rule['source']}"
            )

        if len(forms) != len(rule["replacement_forms"]):

            raise ValueError("Plural structure changed")

        for form, replacement in zip(
            forms, rule["replacement_forms"]
        ):

            form.text = replacement

        # Do not falsely mark translations as finished.
        translation.set("type", "unfinished")

        applied.append({
            "catalogue": filename,
            "context": rule["context"],
            "source": rule["source"],
            "comment": rule["comment"],
            "numerus": rule["numerus"],
            "original_forms": rule["original_forms"],
            "replacement_forms": rule["replacement_forms"],
            "review_status": rule["review_status"],
        })

    # Validate every applicable rule before writing output.

    for path, tree in prepared.items():

        tree.write(
            path,
            encoding="utf-8",
            xml_declaration=True
        )

    report = {
        "registered": len(RULES),
        "applied": len(applied),
        "skipped": len(skipped),
        "findings": applied,
        "skipped_rules": skipped,
    }

    (directory / "correction-report.json").write_text(
        json.dumps(
            report,
            ensure_ascii=False,
            indent=2
        ) + "\n",
        encoding="utf-8"
    )

    print("Translation corrections:", len(applied), flush=True)
    print("Skipped corrections:", len(skipped), flush=True)

    return report
